//! # Resume Data Integrity Management
//!
//! Implements SR-14 and INV-14:
//! - All fastresume / resume metadata generated by the Engine or Core is tagged with HMAC-SHA256.
//! - Constant-time comparison via subtle::ConstantTimeEq prevents timing side-channels.
//! - Any tampered or corrupt resume data causes verification failure so state machine flags as Suspect.

use hmac::{Hmac, Mac};
use sha2::Sha256;
use subtle::ConstantTimeEq;
use thiserror::Error;

type HmacSha256 = Hmac<Sha256>;

#[derive(Debug, Error, PartialEq, Eq)]
pub enum ResumeIntegrityError {
    #[error("Invalid HMAC key length")]
    InvalidKeyLength,
    #[error("Resume data integrity check failed: HMAC mismatch (corrupt or tampered)")]
    TagMismatch,
    #[error("Resume payload exceeds maximum allowable size")]
    PayloadTooLarge,
    #[error("Malformed resume envelope header")]
    MalformedEnvelope,
}

/// Compute HMAC-SHA256 integrity tag over resume data bytes.
pub fn compute_resume_tag(data: &[u8], key: &[u8; 32]) -> [u8; 32] {
    let mut mac = HmacSha256::new_from_slice(key)
        .expect("HMAC-SHA256 accepts 32-byte keys");
    mac.update(data);
    let result = mac.finalize();
    let mut tag = [0u8; 32];
    tag.copy_from_slice(&result.into_bytes());
    tag
}

/// Verify HMAC-SHA256 integrity tag in constant-time.
pub fn verify_resume_tag(data: &[u8], key: &[u8; 32], expected_tag: &[u8; 32]) -> Result<(), ResumeIntegrityError> {
    let actual_tag = compute_resume_tag(data, key);
    let match_result = actual_tag.ct_eq(expected_tag);
    if match_result.into() {
        Ok(())
    } else {
        Err(ResumeIntegrityError::TagMismatch)
    }
}

/// Authenticated Resume Envelope encapsulating payload, metadata, and HMAC tag.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AuthenticatedResumeEnvelope {
    pub version: u32,
    pub info_hash: [u8; 20],
    pub payload: Vec<u8>,
    pub tag: [u8; 32],
}

impl AuthenticatedResumeEnvelope {
    pub const CURRENT_VERSION: u32 = 1;
    pub const MAX_RESUME_SIZE: usize = 16 * 1024 * 1024; // 16 MiB limit

    /// Create and sign a new resume envelope with the given secret key.
    pub fn new(info_hash: [u8; 20], payload: Vec<u8>, key: &[u8; 32]) -> Result<Self, ResumeIntegrityError> {
        if payload.len() > Self::MAX_RESUME_SIZE {
            return Err(ResumeIntegrityError::PayloadTooLarge);
        }

        let mut data_to_authenticate = Vec::with_capacity(4 + 20 + payload.len());
        data_to_authenticate.extend_from_slice(&Self::CURRENT_VERSION.to_be_bytes());
        data_to_authenticate.extend_from_slice(&info_hash);
        data_to_authenticate.extend_from_slice(&payload);

        let tag = compute_resume_tag(&data_to_authenticate, key);

        Ok(Self {
            version: Self::CURRENT_VERSION,
            info_hash,
            payload,
            tag,
        })
    }

    /// Verify envelope integrity against secret key.
    pub fn verify(&self, key: &[u8; 32]) -> Result<(), ResumeIntegrityError> {
        if self.payload.len() > Self::MAX_RESUME_SIZE {
            return Err(ResumeIntegrityError::PayloadTooLarge);
        }

        let mut data_to_authenticate = Vec::with_capacity(4 + 20 + self.payload.len());
        data_to_authenticate.extend_from_slice(&self.version.to_be_bytes());
        data_to_authenticate.extend_from_slice(&self.info_hash);
        data_to_authenticate.extend_from_slice(&self.payload);

        verify_resume_tag(&data_to_authenticate, key, &self.tag)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_resume_envelope_verifies() {
        let key = [0x42u8; 32];
        let info_hash = [0x11u8; 20];
        let payload = b"libtorrent-resume-data-chunk-valid".to_vec();

        let envelope = AuthenticatedResumeEnvelope::new(info_hash, payload, &key).expect("envelope created");
        assert_eq!(envelope.verify(&key), Ok(()));
    }

    #[test]
    fn test_tampered_payload_rejected() {
        let key = [0x42u8; 32];
        let info_hash = [0x11u8; 20];
        let payload = b"unmodified-resume-bytes".to_vec();

        let mut envelope = AuthenticatedResumeEnvelope::new(info_hash, payload, &key).unwrap();
        // Tamper with payload byte
        envelope.payload[0] ^= 0xFF;

        assert_eq!(envelope.verify(&key), Err(ResumeIntegrityError::TagMismatch));
    }

    #[test]
    fn test_tampered_info_hash_rejected() {
        let key = [0x42u8; 32];
        let info_hash = [0x11u8; 20];
        let payload = b"unmodified-resume-bytes".to_vec();

        let mut envelope = AuthenticatedResumeEnvelope::new(info_hash, payload, &key).unwrap();
        envelope.info_hash[0] ^= 0x01;

        assert_eq!(envelope.verify(&key), Err(ResumeIntegrityError::TagMismatch));
    }

    #[test]
    fn test_wrong_key_rejected() {
        let key1 = [0x42u8; 32];
        let key2 = [0x99u8; 32];
        let info_hash = [0x11u8; 20];
        let payload = b"unmodified-resume-bytes".to_vec();

        let envelope = AuthenticatedResumeEnvelope::new(info_hash, payload, &key1).unwrap();
        assert_eq!(envelope.verify(&key2), Err(ResumeIntegrityError::TagMismatch));
    }
}
